/**
 * Cursor-managed durable storage for hosted agents.
 *
 * Uses the control-plane storage proxy with the deployment pod credential.
 * The proxy scopes each request to the authenticated deployment, and the
 * engine never receives a database URL. Cursor manages its storage
 * environment variables; do not add them to `hosting.secretNames`.
 */
import { injectActiveTraceContext } from "../otel.js";
/**
 * Same default as {@link cursorExternalApiUrl} in the CLI credentials module,
 * kept local so this storage entrypoint does not import CLI dependencies.
 */
const DEFAULT_CURSOR_EXTERNAL_API_URL = "https://api.cursor.com";
/**
 * Deployment identifier for diagnostics and self-hosted compatibility.
 * The proxy scopes managed-storage requests by pod credential.
 */
export const AGENT_SERVE_DEPLOYMENT_ID_ENV_VAR = "AGENT_SERVE_DEPLOYMENT_ID";
/**
 * Environment variables reserved for Cursor-managed storage. Do not include
 * these names in `hosting.secretNames`.
 */
export const CURSOR_HOSTED_STORAGE_ENV_VARS = [
    AGENT_SERVE_DEPLOYMENT_ID_ENV_VAR,
];
/**
 * Marker stamped on {@link cursorHostedStorage} so the engine can prefer
 * Cursor-managed durable state for session listing. It survives a
 * `defineStorage` spread.
 * Explicit `unique symbol` annotation required for `--isolatedDeclarations`
 * (TS9010).
 */
export const CURSOR_HOSTED_STORAGE = Symbol.for("@cursor/july.storage.cursor-hosted");
/** True when `value` is (or was built from) {@link cursorHostedStorage}. */
export function isCursorHostedStorage(value) {
    if (typeof value !== "object" || value === null) {
        return false;
    }
    return Object.getOwnPropertyDescriptor(value, CURSOR_HOSTED_STORAGE)?.value === true;
}
const STORAGE_RPC_ERROR_CODES = new Set([
    "agentsdk_kv_credential_missing",
    "agentsdk_kv_cursor_invalid",
    "agentsdk_kv_deployment_unbound",
    "agentsdk_kv_key_invalid",
    "agentsdk_kv_request_invalid",
    "agentsdk_kv_storage_not_allowed",
    "agentsdk_kv_value_invalid",
    "agentsdk_kv_version_invalid",
]);
export class StorageRpcError extends Error {
    constructor(message, reasonCode, status) {
        super(message);
        this.code = "agent_dependency_failed";
        this.name = "StorageRpcError";
        this.reasonCode = reasonCode;
        this.status = status;
    }
}
function toCasResult(response) {
    if (response.ok) {
        if (response.version === null) {
            throw new Error("cursorHostedStorage: CAS success without a version token");
        }
        return { ok: true, version: response.version };
    }
    const current = response.current === null
        ? undefined
        : {
            value: response.current.value ?? null,
            version: response.current.version,
        };
    return { ok: false, current };
}
function resolveApiKey(options) {
    const configured = options.resolveApiKey?.() ?? options.apiKey;
    const key = (configured ?? process.env.CURSOR_API_KEY)?.trim();
    if (key === undefined || key === "") {
        throw new Error("cursorHostedStorage requires CURSOR_API_KEY (deployment pod credential on Cursor hosting)");
    }
    return key;
}
function resolveBaseUrl(options) {
    const raw = (options.baseUrl ??
        process.env.CURSOR_API_BASE_URL ??
        DEFAULT_CURSOR_EXTERNAL_API_URL).trim();
    return raw.endsWith("/") ? raw.slice(0, -1) : raw;
}
/**
 * Send one authenticated request through the control-plane proxy.
 */
export async function storageRpc(options, path, body) {
    const baseUrl = resolveBaseUrl(options);
    const apiKey = resolveApiKey(options);
    const fetchImpl = options.fetch ?? globalThis.fetch;
    if (typeof fetchImpl !== "function") {
        throw new Error("cursorHostedStorage requires fetch");
    }
    const headers = new Headers({
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
    });
    injectActiveTraceContext(headers);
    const response = await fetchImpl(`${baseUrl}${path}`, {
        method: "POST",
        headers,
        body: JSON.stringify(body),
    });
    const text = await response.text();
    let parsed;
    try {
        parsed = text.length === 0 ? {} : JSON.parse(text);
    }
    catch {
        throw new Error(`cursorHostedStorage ${path} returned non-JSON (${response.status})`);
    }
    if (!response.ok) {
        const error = parsed !== null &&
            typeof parsed === "object" &&
            "error" in parsed &&
            typeof parsed.error === "string"
            ? parsed.error
            : `HTTP ${response.status}`;
        const candidate = parsed !== null &&
            typeof parsed === "object" &&
            "code" in parsed &&
            typeof parsed.code === "string"
            ? parsed.code
            : undefined;
        const code = candidate !== undefined && STORAGE_RPC_ERROR_CODES.has(candidate)
            ? candidate
            : "agentsdk_storage_http_error";
        throw new StorageRpcError(`cursorHostedStorage ${path}: ${error}`, code, response.status);
    }
    // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the caller names the JSON shape; this helper cannot validate an arbitrary T
    return parsed;
}
/**
 * Cursor-managed durable storage methods. Requests use the control-plane
 * proxy and deployment pod credential. Spread into `defineStorage({...})`.
 */
export function cursorHostedStorage(options = {}) {
    return {
        [CURSOR_HOSTED_STORAGE]: true,
        async put(key, value) {
            await storageRpc(options, "/internal/agent-serve/storage/kv/put", {
                key,
                value,
            });
        },
        async get(key) {
            const result = await storageRpc(options, "/internal/agent-serve/storage/kv/get", { key });
            if (!result.found) {
                return undefined;
            }
            return result.value ?? undefined;
        },
        async delete(key) {
            await storageRpc(options, "/internal/agent-serve/storage/kv/delete", {
                key,
            });
        },
        async list(prefix) {
            const result = await storageRpc(options, "/internal/agent-serve/storage/kv/list", { prefix });
            return result.entries;
        },
        async listNewest(prefix, limit) {
            // Same route; the server orders the prefix range by row write time
            // and caps the rows instead of returning the whole range.
            const result = await storageRpc(options, "/internal/agent-serve/storage/kv/list", {
                prefix,
                limit,
                newestFirst: true,
            });
            return result.entries;
        },
        // Conditional writes over the same proxy (server routes: see the CAS
        // wire-protocol block above). The proxy scopes rows from the service
        // account, so ctx is not part of the wire contract.
        cas: {
            async getWithVersion(key) {
                const result = await storageRpc(options, "/internal/agent-serve/storage/kv/get-with-version", { key });
                if (!result.found || result.version === null) {
                    return undefined;
                }
                return { value: result.value ?? null, version: result.version };
            },
            async putIfAbsent(key, value) {
                const result = await storageRpc(options, "/internal/agent-serve/storage/kv/put-if-absent", { key, value });
                return toCasResult(result);
            },
            async putIfVersion(key, value, expectedVersion) {
                const result = await storageRpc(options, "/internal/agent-serve/storage/kv/put-if-version", { key, value, expectedVersion });
                return toCasResult(result);
            },
            async listKeys(prefix) {
                const result = await storageRpc(options, "/internal/agent-serve/storage/kv/list-keys", { prefix });
                if (result.truncated === true) {
                    // Callers treat the result as the complete key set; a silently
                    // capped scan hides missing keys. Fail loudly until pagination
                    // lands.
                    throw new Error(`cursorHostedStorage: listKeys("${prefix}") exceeded the server's row cap and was truncated; the result is incomplete`);
                }
                return result.keys;
            },
        },
        evals: {
            async put(run, ctx) {
                await storageRpc(options, "/internal/agent-serve/storage/evals/put", {
                    agentName: ctx.agentName,
                    run,
                });
            },
            async delete(runId, ctx) {
                await storageRpc(options, "/internal/agent-serve/storage/evals/delete", {
                    agentName: ctx.agentName,
                    runId,
                });
            },
            async list(ctx) {
                const result = await storageRpc(options, "/internal/agent-serve/storage/evals/list", { agentName: ctx.agentName });
                return result.runs;
            },
        },
    };
}
